import assert from 'node:assert/strict';
import {HeadOrbit} from './head-orbit.mjs';
const sr=48000;
function impulse(angle){const s=new HeadOrbit(sr);s.setPose(angle,1,true);const l=[],r=[];for(let i=0;i<96;i++){s.process(i===0?1:0,0,1);l.push(s.left);r.push(s.right);}return{l,r};}
const peak=a=>a.reduce((best,x,i)=>Math.abs(x)>Math.abs(a[best])?i:best,0);
const right=impulse(Math.PI/2),left=impulse(-Math.PI/2);assert.ok(peak(right.r)<peak(right.l));assert.ok(peak(left.l)<peak(left.r));assert.ok(peak(right.l)-peak(right.r)<=32);assert.ok(Math.max(...right.r)>Math.max(...right.l));
const s=new HeadOrbit(sr);s.reset(0);let first,last;for(let i=0;i<sr*4;i++){s.process(Math.sin(i*.02),.25,.7);assert.ok(Number.isFinite(s.left)&&Number.isFinite(s.right));assert.ok(Math.abs(s.left)<=1&&Math.abs(s.right)<=1);if(i===sr/2)first=s.side;if(i===sr*2)last=s.side;}assert.ok(Math.abs(first-last)>.5);s.clear();assert.ok(s.history.every(x=>x===0));
globalThis.sampleRate=sr;globalThis.AudioWorkletProcessor=class{constructor(){this.port={postMessage(){}};}};let P;globalThis.registerProcessor=(_,p)=>P=p;await import('./cortex-worklet.js');for(const cap of[4,8,16]){const p=new P();p.port.onmessage({data:{type:'params',value:{active:true,orbitEnabled:true,binaural:true,orbitRate:.5,orbitDepth:1,droneEnabled:true,voiceLimit:cap,output:1,reverb:1}}});for(let b=0;b<400;b++){if(b%5===0)p.port.onmessage({data:{type:'pulse',event:{group:b%16,strength:1}}});const output=[new Float32Array(128),new Float32Array(128)];p.process([],[output]);for(const c of output)for(const x of c)assert.ok(Number.isFinite(x)&&Math.abs(x)<=1);assert.ok(p.activeVoiceCount()<=cap);}assert.equal(p.renderOrbit,true);assert.equal(p.renderBinaural,false);p.port.onmessage({data:{type:'params',value:{active:false}}});for(let b=0;b<120;b++)p.process([],[[new Float32Array(128),new Float32Array(128)]]);assert.ok(p.slots.every(s=>s.orbit.history.every(x=>x===0)));}
console.log(JSON.stringify({ok:true,impulseLeadSamples:peak(right.l)-peak(right.r),oppositeEarLead:true,motion:true,boundedCaps:[4,8,16],mutuallyExclusive:true,pauseClears:true}));
